import os,re,collections,functools,sys
root='AlgebraicJacobian'
def mod(p):
    return p[:-5].replace('/','.')
files={}
for dp,dn,fn in os.walk(root):
    for f in fn:
        if f.endswith('.lean'):
            p=os.path.join(dp,f); files[mod(p)]=p
files['AlgebraicJacobian']='AlgebraicJacobian.lean'
imports={}
lines={}
umb=set()
for m,p in files.items():
    txt=open(p).read()
    lines[m]=txt.count('\n')+1
    ims=re.findall(r'^import\s+(\S+)',txt,re.M)
    if 'Mathlib' in ims: umb.add(m)
    imports[m]=[i for i in ims if i in files]
# reachable from root
root_mod='AlgebraicJacobian'
seen=set()
st=[root_mod]
while st:
    x=st.pop()
    if x in seen: continue
    seen.add(x)
    st.extend(imports.get(x,[]))
print("modules on disk:",len(files),"reachable from root:",len(seen),"unrooted:",len(files)-len(seen))
print("bare-Mathlib modules:",len(umb),"of which reachable:",len(umb&seen))
print("total lines:",sum(lines.values()),"reachable lines:",sum(lines[m] for m in seen))
# longest chain (depth) by module count
sys.setrecursionlimit(10000)
memo={}
def depth(m):
    if m in memo: return memo[m]
    memo[m]=(0,[m])
    best=(0,[m])
    for d in imports.get(m,[]):
        k,path=depth(d)
        if k+1>best[0]: best=(k+1,path+[m])
    memo[m]=best
    return best
k,path=depth(root_mod)
print("longest import chain from root:",k+1,"modules")
print(" -> ".join(p.replace('AlgebraicJacobian.','') for p in path[-15:]))
# biggest files reachable
big=sorted(((lines[m],m) for m in seen),reverse=True)[:20]
print("\nlargest reachable modules:")
for l,m in big: print(f"  {l:6d} {m.replace('AlgebraicJacobian.','')}{'  [umbrella]' if m in umb else ''}")
print("\nover 500 lines:",sum(1 for m in seen if lines[m]>500),"; over 1500:",sum(1 for m in seen if lines[m]>1500))
